import { OpeningHoursItem } from "@parksandresorts/webapiproxy-types";
import { createDate, DateHelper, SessionStorageHelper } from "../helpers";
import { EntryVariant } from "../types/services/purchase-flow-service-types";
import ServiceHelper from "./service-helper";

class OpeningHoursService {
  private promises: Record<string, Promise<OpeningHoursItem[]> | null> = {};

  async getAllDates(): Promise<OpeningHoursItem[]> {
    const key = "OpeningHoursService-getAllDates";
    let response: OpeningHoursItem[] = SessionStorageHelper.getItem(key);

    if (response) {
      return response;
    }

    if (this.promises[key]) {
      return this.promises[key];
    }

    this.promises[key] = ServiceHelper.fetchGet<OpeningHoursItem[]>("/openinghours/");
    response = await this.promises[key];

    const timeStampDate = createDate();
    timeStampDate.setMinutes(timeStampDate.getMinutes() + 5);
    SessionStorageHelper.setItem(key, response, timeStampDate.getTime());

    this.promises[key] = null;

    return response;
  }

  async getDate(date: string) {
    const response = await ServiceHelper.fetchGet<OpeningHoursItem[]>(`/openinghours/${date}`);
    return response;
  }

  /**
   * Checks if the time of day has passed for a given entry variant.
   *
   * Time for morning end is hardcoded awaiting an API update.
   */
  hasTimeOfDayPassedEntryVariant(entryVariant: EntryVariant["id"]): boolean {
    switch (entryVariant) {
      case "Morning": {
        return DateHelper.hasTimePassedToday("16:00");
      }
      default: {
        return false;
      }
    }
  }
}

const helper = new OpeningHoursService();
export default helper;
